#include <algorithm>
#include <deque>
#include <functional>
#include <iostream>
#include <map>
#include <numeric>
#include <set>
#include <stdexcept>
#include <vector>
using namespace std;using V=vector<int>;using G=vector<int>;using Group=vector<V>;using ll=long long;
void need(bool x,const char*s){if(!x)throw runtime_error(s);}bool edge(const G&a,int i,int j){return a[i]>>j&1;}
Group quotient_maps(const G&a,bool anti){int n=a.size();V p(n);iota(p.begin(),p.end(),0);Group ans;do{bool ok=true;for(int i=0;i<n&&ok;i++)for(int j=0;j<i;j++)if(edge(a,i,j)!=(edge(a,p[i],p[j])^anti)){ok=false;break;}if(ok)ans.push_back(p);}while(next_permutation(p.begin(),p.end()));return ans;}
Group graph_maps(const G&a,bool anti){int n=a.size();V p(n,-1),order(n),deg(n);iota(order.begin(),order.end(),0);for(int i=0;i<n;i++)deg[i]=__builtin_popcount((unsigned)a[i]);stable_sort(order.begin(),order.end(),[&](int i,int j){return deg[i]<deg[j];});Group ans;function<void(int,int)>dfs=[&](int pos,int used){if(pos==n){ans.push_back(p);return;}int v=order[pos];for(int w=0;w<n;w++)if(!(used>>w&1)&&(anti?deg[v]+deg[w]==n-1:deg[v]==deg[w])){bool ok=true;for(int j=0;j<pos;j++){int u=order[j];if(edge(a,v,u)!=(edge(a,w,p[u])^anti)){ok=false;break;}}if(ok){p[v]=w;dfs(pos+1,used|(1<<w));p[v]=-1;}}};dfs(0,0);sort(ans.begin(),ans.end());return ans;}
G blow(const G&q,const V&w){int n=accumulate(w.begin(),w.end(),0);V start(w.size()+1);partial_sum(w.begin(),w.end(),start.begin()+1);G a(n);for(int b=0;b<(int)w.size();b++)for(int j=0;j<w[b];j++){int u=start[b]+j;for(int k=j+1;k<w[b];k++)a[u]|=1<<(start[b]+k);for(int c=0;c<(int)w.size();c++)if(edge(q,b,c))for(int k=0;k<w[c];k++)a[u]|=1<<(start[c]+k);}return a;}
bool fixed(const V&p,const V&w){for(int i=0;i<(int)p.size();i++)if(w[i]!=w[p[i]])return false;return true;}
V lift(const V&p,const V&w,bool anti){V start(w.size()+1);partial_sum(w.begin(),w.end(),start.begin()+1);V ans(start.back());for(int i=0;i<(int)p.size();i++)for(int j=0;j<w[i];j++)ans[start[i]+j]=start[p[i]]+(anti?w[i]-1-j:j);return ans;}
V cycles(const V&p){V used(p.size()),c;for(int i=0;i<(int)p.size();i++)if(!used[i]){int j=i,len=0;do{used[j]=1;j=p[j];len++;}while(j!=i);c.push_back(len);}sort(c.begin(),c.end());return c;}
vector<int> blocks(const G&a){int n=a.size();V good;for(int S=1;S<(1<<n);S++){bool ok=true;for(int v=0;v<n&&ok;v++)if(!(S>>v&1)){int z=a[v]&S;if(z&&z!=S)ok=false;}if(!ok)continue;for(int i=0;i<n&&ok;i++)if(S>>i&1)for(int j=0;j<i&&ok;j++)if(S>>j&1)for(int k=0;k<j;k++)if(S>>k&1){bool e1=edge(a,i,j),e2=edge(a,j,k),e3=edge(a,k,i);if(e1==e2&&e2==e3){ok=false;break;}}if(ok)good.push_back(S);}V maximal;for(int S:good){bool yes=true;for(int T:good)if(T!=S&&(S&T)==S){yes=false;break;}if(yes)maximal.push_back(S);}return maximal;}
int main(){vector<G>bank={{0},{0,5,9,3},{0,5,9,3,15},{2,4,1},{2,4,1,7},{2,4,9,19,7},{2,12,9,17,7},{2,28,9,17,5},{6,12,24,17,3},{22,44,88,49,98,69,11},{60,57,50,36,8,16}};ll physical=0,maps=0,blockchecks=0,orbits=0,optim=0,conjugacy=0;for(const G&q:bank){int k=q.size();auto aut=quotient_maps(q,0),anti=quotient_maps(q,1);need(aut.size()%2==1,"odd group");need(anti.empty()||anti.size()==aut.size(),"anti coset");V bq=blocks(q);need((int)bq.size()==k,"canonical quotient blocks");Group invol;for(auto&p:anti){bool ok=true;for(int i=0;i<k;i++)ok&=p[p[i]]==i;if(ok)invol.push_back(p);}if(!anti.empty()){need(!invol.empty(),"anti involution");for(auto&t:invol){int C=0;for(auto&g:aut){bool commute=true;for(int i=0;i<k;i++)commute&=g[t[i]]==t[g[i]];C+=commute;}need(C*invol.size()==aut.size(),"centralizer conjugacy mass");conjugacy++;}}
for(int n=k;n<=11;n++){vector<V>W;V w(k,1);function<void(int,int)>gen=[&](int i,int rem){if(i==k-1){if(rem>=1){w[i]=rem;W.push_back(w);}return;}for(int a=1;a<=rem-(k-i-1);a++){w[i]=a;gen(i+1,rem-a);}};gen(0,n);map<V,int>idx;for(int i=0;i<(int)W.size();i++)idx[W[i]]=i;V parent(W.size());iota(parent.begin(),parent.end(),0);function<int(int)>find=[&](int i){while(parent[i]!=i){parent[i]=parent[parent[i]];i=parent[i];}return i;};ll fixedaut=0,fixedanti=0;vector<bool>sc(W.size());for(int t=0;t<(int)W.size();t++){const auto&w=W[t];for(auto&p:aut){V v(k);for(int i=0;i<k;i++)v[p[i]]=w[i];parent[find(t)]=find(idx.at(v));fixedaut+=fixed(p,w);}for(auto&p:anti){fixedanti+=fixed(p,w);sc[t]=sc[t]||fixed(p,w);}if(n<=10){G a=blow(q,w);auto ga=graph_maps(a,0),ha=graph_maps(a,1);Group pg,ph;for(auto&p:aut)if(fixed(p,w))pg.push_back(lift(p,w,0));for(auto&p:anti)if(fixed(p,w))ph.push_back(lift(p,w,1));sort(pg.begin(),pg.end());sort(ph.begin(),ph.end());need(pg==ga&&ph==ha,"literal full map-set lift");need(sc[t]==!ha.empty(),"physical self converse");physical++;maps+=2;if(n<=8){V bb=blocks(a),expected;int off=0;for(int z:w){expected.push_back(((1<<z)-1)<<off);off+=z;}sort(expected.begin(),expected.end());need(bb==expected,"literal maximal chains");blockchecks++;}}}
set<int>U,S;for(int i=0;i<(int)W.size();i++){U.insert(find(i));if(sc[i])S.insert(find(i));}need(fixedaut==(ll)U.size()*aut.size()&&fixedanti==(ll)S.size()*aut.size(),"ordinary and twisted Burnside");orbits++;}
// Reverse breadth-first search on the growth lattice, all mutable masks.
int K=1;V power(k);for(int i=0;i<k;i++){power[i]=K;K*=3;}vector<V>W(K,V(k));vector<bool>sym(K);for(int code=0;code<K;code++){for(int i=0;i<k;i++)W[code][i]=1+(code/power[i])%3;for(auto&p:anti)sym[code]=sym[code]||fixed(p,W[code]);}
for(int mask=0;mask<(1<<k);mask++){V distance(K,-1);deque<int>Q;for(int code=0;code<K;code++)if(sym[code]){distance[code]=0;Q.push_back(code);}while(!Q.empty()){int code=Q.front();Q.pop_front();for(int i=0;i<k;i++)if((mask>>i&1)&&W[code][i]>1){int old=code-power[i];if(distance[old]<0){distance[old]=distance[code]+1;Q.push_back(old);}}}for(int code=0;code<K;code++){int best=-1;for(auto&p:invol){int cost=0;bool feasible=true;for(int i=0;i<k;i++)if(i<p[i]){int j=p[i],v=max(W[code][i],W[code][j]);if(W[code][i]<v&&!(mask>>i&1))feasible=false;if(W[code][j]<v&&!(mask>>j&1))feasible=false;cost+=abs(W[code][i]-W[code][j]);}if(feasible&&(best<0||cost<best))best=cost;}need(best==distance[code],"reverse BFS optimal completion");optim++;}}
if(k==7){map<V,int>A,B;for(auto&p:aut)A[cycles(p)]++;for(auto&p:anti)B[cycles(p)]++;need(A==map<V,int>{{V(7,1),1},{V{7},6},{V{1,3,3},14}},"independent Paley aut types");need(B==map<V,int>{{V{1,2,2,2},7},{V{1,6},14}},"independent Paley anti types");}}
cout<<"{\n  \"status\":\"PASS\",\n  \"quotients\":"<<bank.size()<<",\n  \"physical_blowups\":"<<physical<<",\n  \"exact_map_comparisons\":"<<maps<<",\n  \"maximal_block_controls\":"<<blockchecks<<",\n  \"orbit_order_controls\":"<<orbits<<",\n  \"reverse_BFS_completion_controls\":"<<optim<<",\n  \"centralizer_conjugacy_controls\":"<<conjugacy<<"\n}\n";
}
